    @staticmethod
    def _request(service, method, char_code, key_code=None, shift=False, vk_down=()):
        event = dict(ime_smoke_runner.BASE_EVENT)
        event["keyStates"] = list(event["keyStates"])
        for vk in (VK_SHIFT if shift else None, *vk_down):
            if vk is not None:
                event["keyStates"][vk] = 0x80
        event.update(method=method, charCode=char_code,
                     keyCode=char_code if key_code is None else key_code, seqNum=1)
        return service.handleRequest(event)

    @staticmethod
    def press(service, char_code, key_code=None, shift=False, vk_down=()):
        """Filter first; let the service consume the key only if it claims it."""
        filtered = ChebihuaServiceTests._request(service, "filterKeyDown",
                                                 char_code, key_code, shift, vk_down)
        if not filtered.get("return"):
            return filtered
        return ChebihuaServiceTests._request(service, "onKeyDown",
                                             char_code, key_code, shift, vk_down)

    @staticmethod
    def force_press(service, char_code, key_code):
        """Filter and down, unconditionally.

        The `` ` `` menu is handled in onKeyDown alone, and press() stops early
        when the filter declines a key — which the arrow keys do. The real
        client sends both messages for every key, so this mirrors it.
        """
        ChebihuaServiceTests._request(service, "filterKeyDown", char_code, key_code)
        return ChebihuaServiceTests._request(service, "onKeyDown", char_code, key_code)

    def activate_chebihua(self):
        from input_methods.chebihua import chebihua_ime, table_loaders

        # Force a fresh table load so the Cin binds the APPDATA of this
        # test: the holder's own reset seam, not a poke at module globals.
        table_loaders.CinTable.reset()

        service = chebihua_ime.CheBihuaTextService(ime_smoke_runner.FakeClient())
        reply = service.handleRequest(
            {"method": "onActivate", "isKeyboardOpen": True, "seqNum": 1})
        self.assertTrue(reply.get("success"), reply)
        # The module's own bounded join: no 500×20 ms poll out here, and a
        # load that failed raises TableLoadError naming the table instead
        # of dying on a bare assertion below.
        table_loaders.CinTable.wait_until_ready(timeout=10)
